import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('audioclip_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const fields=['gain','pitchCoarse','pitchFine','loopStart','loopEnd','warpMode','warping','fadeInLength','fadeOutLength'];
function setup(sim,kind){const clip=sim.state.tracks[0].clips[0];Object.assign(clip,{kind:'audio',isAudio:true,gain:1,pitchCoarse:0,pitchFine:0,loopStart:0,loopEnd:4,warpMode:0,warping:true,fadeInLength:0,fadeOutLength:0});if(kind==='arrangement'){const arranged={...structuredClone(clip),ref:'arrangement-clip:track-1:0',objectIdentity:'simulator:arrangement-clip:0'};for(const f of fields)if(!['loopStart','loopEnd'].includes(f))delete arranged[f];sim.state.arrangementClips.push({trackRef:'track:track-1',clip:arranged});}}
function params(kind){return kind==='arrangement'?{clipRef:'arrangement-clip:track-1:0',loopStart:0.5,loopEnd:3.5}:{clipRef:'clip:clip-1',gain:0.4,pitchCoarse:12,pitchFine:-20.5,loopStart:0.25,loopEnd:3.75,warpMode:3,warping:false,fadeInLength:0.1,fadeOutLength:0.2};}
const rows=[];for(const action of ['preview','apply']){const valid=action==='preview'?{clipRef:'clip:clip-1',gain:0.4}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of (action==='preview'?['clipRef',...fields]:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-51,-50,-48,-1,0,0.5,1,16,17,48,49,50,51,100001,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,'session-midi');const host=new McpHost(sim);let result;try{result=clean(await host[action==='preview'?'liveAudioClipPreviewAsync':'liveAudioClipApplyAsync'](1,args));}catch(e){result={error:e.message};}rows.push({action,args,result});}}
const workflows=[];for(const kind of ['session','arrangement'])for(const scenario of ['normal','expire','epoch','identity-edit','source-content','unavailable-field','not-audio','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-float32','apply-drift','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;const source=kind==='arrangement'?sim.state.arrangementClips[0].clip:sim.state.tracks[0].clips[0];if(scenario==='missing-identity')delete source.objectIdentity;if(scenario==='unavailable-field')source.availableAudioFields=[];if(scenario==='not-audio')source.isAudio=false;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';}if(!fired&&['apply-float32','apply-drift'].includes(fault)){fired=true;if(fault==='apply-float32'){for(const f of fields)if(typeof source[f]==='number')source[f]=Math.fround(source[f]);}else source.loopEnd+=0.01;}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args=params(kind);const preview=await host.liveAudioClipPreviewAsync(1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveAudioClipApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')source.objectIdentity='other';if(scenario==='source-content')source.loopEnd=100;if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')source.objectIdentity='other';if(scenario==='undo-other-content')source.loopEnd=100;if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-audio-clip-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
